extraScenes.forEach(x=>SCENES.push({id:x[0],name:x[1],group:x[2],module:x[3],view:x[4],state:x[5],note:x[6],role:x[7],index:SCENES.length+1}));
const managedSceneIds=['p-quota','p-quota-error','p-edit-bound','p-delete','p-delete-blocked','p-paused'];
SCENES.forEach(s=>{s.baseRole=s.role||(s.id==='w-assign'?'admin':s.state==='web'||managedSceneIds.includes(s.id)?'senior':'operator');s.role=s.baseRole});
const v2Accounts=[['208','B站','星河玩游戏','登录正常'],['216','百度','星河游戏资讯','登录正常']];
let taskOrigin='proxy',taskReturn='p-list',taskPhase='running',createdManaged=false;
try{const saved=JSON.parse(localStorage.getItem('qifei-design-task-v2')||'null');if(saved?.phase)taskPhase=saved.phase}catch{}
function persistTask(){try{localStorage.setItem('qifei-design-task-v2',JSON.stringify({phase:taskPhase}))}catch{}}
const textMap=[['Browser Profile','窗口'],['BitBrowser','比特'],['Local Agent','本机服务'],['Cloud Web','网页版'],['Cloud','系统'],['Desktop','桌面端'],['Profile','窗口'],['系统管理','系统托管'],['代理管理方式','代理管理方式'],['正式运营事实','运营信息'],['正式关系','托管关系'],['实际镜像','当前配置'],['窗口镜像','窗口信息'],['镜像','信息'],['读回','核实'],['Host','代理地址'],['Port','端口'],['动态API','动态代理'],['动态 API','动态代理'],['API配置','提取配置'],['供应商API','提取链接'],['动态代理API','提取链接'],['保存代理资源','保存'],['保存代理资料','保存'],['保存配额','保存'],['敏感链接仅供授权的本机提取，不进入普通列表或日志。','请输入供应商提供的提取链接。'],['按正式关联的窗口计数，与平台账号数量无关。','按窗口计数，同一窗口的多个平台账号不重复占用。'],['新建浏览器窗口','新增浏览器窗口'],['新建窗口','新增窗口'],['创建并同步','保存'],['保存并核实','保存'],['逐项写入并核实','逐项处理'],['main_user_id','比特账号标识'],['系统 proxy_resource','系统代理资源'],['proxy_resource','代理资源']];
function plain(t){textMap.forEach(([a,b])=>t=t.split(a).join(b));return t}
function tidyStage(){const stage=document.getElementById('stage');const walk=document.createTreeWalker(stage,NodeFilter.SHOW_TEXT);let n;while(n=walk.nextNode())n.nodeValue=plain(n.nodeValue);stage.querySelectorAll('.nav-item').forEach(n=>{if(n.textContent.trim()==='系统托管'&&n.querySelector('svg'))n.lastChild.textContent='系统管理'});stage.querySelectorAll('input,textarea').forEach(n=>{n.placeholder=plain(n.placeholder||'');if(n.type!=='password')n.value=plain(n.value)});stage.querySelectorAll('.scene-hint').forEach(n=>n.remove());stage.querySelectorAll('.scope-label').forEach(n=>n.remove());stage.querySelectorAll('.notice').forEach(n=>{const title=n.querySelector('strong')?.textContent||'';if(/本次同步保护|恢复系统完整|仅修改下面提交的目标字段|本轮不会远程删除|代理台账不直接操作窗口/.test(title))n.remove()});}
function userRole(){return current?.role||'operator'}
function isLocal(){return userRole()==='operator'&&current?.state!=='web'}
function roleList(mod){return mod==='proxy'?(userRole()==='admin'?'p-admin':userRole()==='senior'?'p-senior':'p-list'):(userRole()==='admin'?'w-admin':userRole()==='senior'?'w-senior':'w-list')}
function taskEntry(mod){taskOrigin=mod;taskReturn=roleList(mod);return userRole()==='admin'?'t-admin':userRole()==='senior'?'t-senior':mod==='window'?'t-window':'t-list'}
function accountImpact(){return `<div class="impact-line">${icon('InfoCircle')} 影响此窗口关联的 <strong>2 个账号</strong>：B站、百度</div>`}
function shell(content,mod='window',web=false){const role=userRole(),remote=role!=='operator'||web;return `<div class="app"><aside class="sidebar"><div class="brand"><span class="logo-crop"><img src="assets/logo.png" alt="起飞"></span><div><strong>起飞</strong><small>内容运营平台</small></div></div><div class="nav-heading">工作空间</div><button class="nav-item" data-action="home">${icon('Home')}工作台</button><div class="nav-item">${icon('Browse')}内容挖掘</div><div class="nav-item">${icon('Video')}内容生产</div><div class="nav-item">${icon('Send')}运营执行</div><div class="nav-heading">运营资源</div><button class="nav-item sub ${mod==='window'?'active':''}" data-go="${roleList('window')}">浏览器窗口</button><button class="nav-item sub ${mod==='proxy'?'active':''}" data-go="${roleList('proxy')}">代理管理</button><div class="nav-item sub">社媒账号</div><button class="nav-item sub ${mod==='task'?'active':''}" data-action="tasks">批量任务</button><div class="nav-heading">管理与设置</div><div class="nav-item">${icon('ChartBar')}数据分析</div><div class="nav-item">${icon('Setting')}系统管理</div><div class="side-bottom">${badge(remote?'网页版':'桌面端','blue')}<div>${role==='admin'?'全局管理':'星河运营组'}</div><div style="margin-top:7px">WT Media</div></div></aside><div class="app-right"><header class="topbar"><div class="breadcrumb">运营资源 <span>／　${mod==='task'?'批量任务':mod==='window'?'浏览器窗口':'代理管理'}</span></div><div class="top-right">${!remote?badge(current?.state==='offline'?'本机不可用':'本机已连接',current?.state==='offline'?'orange':'green',true):''}${icon('Notification')}<span class="avatar">${role==='operator'?'林':role==='senior'?'陈':'周'}</span><span>${role==='operator'?'林予安':role==='senior'?'陈以宁':'周闻'} · ${roleNames[role]}</span></div></header><main class="main-content">${content}</main></div></div>`}
function stats(mod){const list=mod==='window'?[['待处理异常','4','orange','异常状态','代理配置不一致'],['系统托管','86','blue','代理管理方式','系统托管'],['比特自管','42','','代理管理方式','比特自管']]:[['可分配代理','18','green','资源状态','启用'],['已用窗口 / 总额度','61 / 96','','',''],['需关注资源','6','orange','资源状态','已到期']];return `<div class="stats v2-stats">${list.map(([label,num,tone,filter,value])=>`<button class="stat ${filter?'clickable':''}" ${filter?`data-action="stat-filter" data-filter-name="${filter}" data-filter-value="${value}"`:''}><span><label>${label}</label><strong class="${tone}">${num}</strong></span>${icon(filter?'ChevronDown':'Desktop')}</button>`).join('')}</div>`}
function windowTable(selected=false){const local=isLocal(),role=userRole();return `<div class="table-wrap"><table class="resource-table window-v2"><colgroup>${[28,43,131,91,78,135,140,55,65,77,248].map(w=>`<col style="width:${w}px">`).join('')}</colgroup><thead><tr><th>${local?'<input class="check" type="checkbox" data-action="select">':''}</th><th>ID</th><th>窗口名称</th><th>${local?'比特分组':'授权运营'}</th><th>代理管理方式</th><th>代理信息</th><th>关联账号</th><th>业务启停</th><th>运行状态</th><th>最近同步</th><th>操作</th></tr></thead><tbody>${windowRows.map((r,i)=>{const detail=role==='admin'?'w-detail-admin':role==='senior'?'w-detail-senior':r[3]==='self'?'w-detail-self':r[6]==='mismatch'?'w-detail-mismatch':'w-detail-managed';const problem=['mismatch','expired','missing'].includes(r[6]);return `<tr data-window-index="${i}" data-search="${e(r.join(' '))}"><td>${local?`<input class="check" type="checkbox" ${selected&&i<3?'checked':''} data-action="select">`:''}</td><td class="entity-id">${r[0]}</td><td><strong>${r[1]}</strong></td><td>${local?r[2]:['林予安','林予安','许知夏','许知夏','林予安','宋嘉言','宋嘉言','林予安'][i]}</td><td>${badge(r[3]==='self'?'比特自管':'系统托管',r[3]==='self'?'':'blue')}</td><td><div class="mono">${r[5]}</div><div class="tiny muted">${r[3]==='system'?r[4]:r[5]==='—'?'直连':'比特当前代理'}</div>${problem?badge(r[6]==='mismatch'?'配置不一致':r[6]==='expired'?'代理已到期':'本机窗口缺失',r[6]==='mismatch'?'orange':'red'):''}</td><td><button class="account-summary" data-go="w-accounts">${getAccounts(i).map(a=>`<span><b>${a[1]}</b> ${a[2]}</span>`).join('')}</button></td><td>${local?'<button class="switch" data-go="w-disable" aria-label="停用窗口"></button>':badge('启用','green')}</td><td class="tiny ${r[6]==='missing'?'muted':''}">${r[6]==='missing'?'未知':r[7]==='active'?'● 已打开':'○ 已关闭'}</td><td class="tiny muted">10-27<br>14:32</td><td><div class="row-actions">${btn('详情',detail,'text')}${local?btn(r[7]==='active'?'关闭':'打开','!window','text',r[6]==='missing')+btn('编辑','w-edit','text',r[6]==='missing')+btn(problem?'处理异常':'管理代理',r[6]==='mismatch'?'w-mismatch':r[6]==='missing'?'w-missing':r[6]==='expired'?'w-replace':'w-mode','text')+btn('运营备注','w-note','text'):btn('运营备注','w-note','text')+(role==='admin'?btn('授权','w-assign','text'):'')}</div></td></tr>`}).join('')}</tbody></table></div>`}
function proxyTable(){const manager=userRole()!=='operator',local=isLocal();return `<div class="table-wrap"><table class="resource-table proxy-v2"><colgroup>${[29,65,150,100,95,80,82,71,93,88,210].map(w=>`<col style="width:${w}px">`).join('')}</colgroup><thead><tr><th>${local?'<input class="check" type="checkbox" data-action="select-proxy">':''}</th><th>ID</th><th>代理名称 / 地址</th><th>地区 / 供应商</th><th>来源</th><th>已用 / 额度</th><th>资源启停</th><th>有效期</th><th>检测结果</th><th>到期时间</th><th>操作</th></tr></thead><tbody>${proxyRows.map((r,i)=>`<tr data-search="${e(r.join(' '))}"><td>${local?'<input class="check" type="checkbox" data-action="select-proxy">':''}</td><td class="entity-id">${r[0]}</td><td><strong>${r[1]}</strong><div class="mono muted">${r[3]}</div></td><td>${r[4]}<div class="tiny muted">${r[5]}</div></td><td>${badge(r[6]==='api'?'动态代理':'静态地址',r[6]==='api'?'blue':'')}</td><td>${r[8]} / ${r[9]}<div class="progress"><span style="width:${100*r[8]/r[9]}%"></span></div></td><td>${manager?`<button class="switch ${r[7]==='paused'?'off':''}" data-go="p-paused" aria-label="${r[7]==='paused'?'启用代理':'停用代理'}"></button>`:badge(r[7]==='paused'?'停用':'启用',r[7]==='paused'?'':'green')}</td><td>${badge(r[7]==='expired'?'已到期':'有效',r[7]==='expired'?'red':'')}</td><td>${badge(r[7]==='unknown'?'未检测':r[7]==='fail'?'连接失败':r[7]==='ok'?'正常':'待复检',r[7]==='fail'?'red':r[7]==='ok'?'green':'')}</td><td class="tiny muted">${r[10]}</td><td><div class="row-actions">${btn('详情',r[7]==='expired'?'p-expired':r[6]==='api'?'p-detail-api':manager?'p-detail-senior':'p-detail','text')}${btn('编辑',manager&&r[8]?'p-edit-bound':'p-edit','text')}${local&&r[7]!=='paused'?btn('检测','p-checking','text'):''}${manager?btn('配额','p-quota','text'):''}${manager&&r[8]===0?btn('删除','p-delete','text danger-text'):''}</div></td></tr>`).join('')}</tbody></table></div>`}
function pagination(mod){return `<div class="pagination"><span>共 ${mod==='window'?128:24} 条</span><div class="page-numbers"><span>8 条 / 页　</span>${[1,2,3].map(i=>`<button class="page-number ${i===1?'selected':''}" data-action="page">${i}</button>`).join('')}${mod==='window'?'<span>…</span><button class="page-number" data-action="page">16</button>':''}</div></div>`}
const v1List=listPage;
listPage=function(s){if(s.module==='task')return taskList(s);const local=isLocal(),role=userRole(),isW=s.module==='window',state=s.view==='list'?s.state:'default';let actions=btn('批量任务','!tasks');if(isW&&local)actions=btn(icon('Refresh')+'同步窗口','w-sync-issues')+actions+btn(icon('Add')+'新增窗口','w-create','primary');if(!isW)actions+=btn(icon('Upload')+'批量导入','p-import')+btn(icon('Add')+'新增代理','p-create','primary');if(state==='permission')actions='';let content=`<div class="page-header"><div><h1 class="page-title">${isW?'浏览器窗口':'代理管理'}</h1>${role!=='operator'?`<span class="scope-caption">${role==='admin'?'全部团队':'星河运营组 · 负责游戏范围'}</span>`:''}</div><div class="actions">${actions}</div></div>`;
if(state==='offline')content+=notice('比特未连接，暂时无法操作窗口','请启动比特并登录绑定账号。','orange',btn('重新检测','w-sync-issues','small'));
content+=state==='permission'?'':stats(s.module);
let filters=`<div class="filters"><div class="field wide"><label>搜索</label><input class="input" data-filter placeholder="${isW?'窗口名称 / ID / 备注':'代理名称 / 地址 / 供应商'}" ${state==='noresult'?'value="未找到的窗口"':''}></div>${field(isW?'代理管理方式':'地区','全部',{options:isW?['全部','系统托管','比特自管']:['全部','上海','广州','杭州']}).replace('class="field "','class="field medium"')}${field(isW?'异常状态':'资源状态','全部',{options:isW?['全部','代理配置不一致','代理到期','本机缺失']:['全部','启用','停用','已到期']}).replace('class="field "','class="field medium"')}${field(isW?(local?'比特分组':'授权运营'):'供应商','全部',{options:isW?(local?['全部','主力账号组','备用账号组']:['全部','林予安','许知夏','宋嘉言']):['全部','星云网络','云桥网络']}).replace('class="field "','class="field medium"')}<div class="actions">${btn('查询','!filter','primary')}${btn('重置',roleList(s.module))}</div></div>`;
let table=isW?windowTable(state==='selected'):proxyTable();if(state==='selected')table=`<div class="selection"><span>已选择 <strong>3</strong> 个窗口</span><div class="actions">${btn('批量设置代理','w-batch-bind','small')}${btn('批量修改分组','w-batch-edit','small')}${btn('批量改为比特自管','w-batch-self','small')}${btn('取消选择','w-list','text')}</div></div>`+table;
if(['empty','noresult','error','permission'].includes(state)){const title=state==='permission'?'暂无查看权限':state==='error'?'加载失败，请重试':state==='noresult'?'没有符合条件的记录':isW?'还没有浏览器窗口':'还没有代理资源';const hint=state==='permission'?'请联系管理员确认访问范围。':state==='error'?'原筛选条件已保留。':state==='noresult'?'尝试调整或清除筛选条件。':isW?'同步已有窗口，或新增一个窗口。':'新增代理，或批量导入已有资源。';const action=state==='permission'?'':state==='error'?btn('重试',roleList(s.module),'primary'):state==='noresult'?btn('清除筛选',roleList(s.module)):isW?btn('同步窗口','w-sync','primary')+btn('新增窗口','w-create'):btn('新增代理','p-create','primary')+btn('批量导入','p-import');table=`<div class="empty-state"><div class="empty-symbol">${icon(state==='permission'?'LockOn':state==='error'?'ErrorCircle':'Search')}</div><h3>${title}</h3><p>${hint}</p><div class="actions">${action}</div></div>`}
if(state==='loading')table=`<table><thead><tr>${['ID','窗口名称','代理管理方式','代理信息','关联账号','运行状态','操作'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${Array.from({length:8},()=>`<tr>${Array.from({length:7},()=>'<td style="height:68px"><span class="skeleton" style="width:75%"></span></td>').join('')}</tr>`).join('')}</tbody></table>`;
return shell(content+`<section class="panel">${state==='permission'?'':filters}${table}${['empty','noresult','error','permission'].includes(state)?'':pagination(s.module)}</section>`,s.module,!local)};
