function jobModel(state,forced){const defaults={running:'9826',partial:'9826',waiting:'9824',uncertain:'9822',success:'9823',failed:'9818',retried:'9827'};const id=forced||focusTask||defaults[state];let rec=taskRecords.find(r=>r[0]===id);if(state==='retried'){const old=taskRecords.find(r=>r[0]===retrySource)||taskRecords[1];return{id:lastRetryId,name:old[1]+' · 失败项重试',type:old[2],origin:old[3],state:'retried',total:Number(old[8])||1,ok:Number(old[8])||1,fail:0,skip:0,unknown:0,pending:0,source:old[0]}}
if(!rec)rec=taskRecords.find(r=>r[0]===defaults[state])||taskRecords[1];let status=rec[0]==='9826'?state:rec[5];let ok=Number(rec[7]),fail=Number(rec[8]),skip=Number(rec[9]),unknown=status==='uncertain'?2:0,total=Number(rec[6]);if(rec[0]==='9826'){[ok,fail,skip,unknown]=status==='running'?[3,0,2,0]:status==='partial'?[3,1,2,0]:[6,0,0,0]}

return{id:rec[0],name:rec[1],type:rec[2],origin:rec[3],state:status,total,ok,fail,skip,unknown,pending:total-ok-fail-skip-unknown,started:'2026-'+rec[10],source:rec[11]}}
function taskDetail(s){const m=jobModel(s.state||'partial',s.forceId),role=userRole();const noticeText=m.state==='running'?notice('任务正在处理','关闭详情不会取消任务，可从“批量任务”再次进入。'):m.state==='waiting'?notice('等待原执行电脑恢复连接','请由林予安在原桌面端连接比特后继续。','orange'):m.state==='uncertain'?notice('有 2 项结果尚未确认','请先核实当前配置，避免重复操作。','orange'):m.state==='partial'?notice('部分记录未完成','成功项已保留，可仅重试失败项。','orange'):'';
let items=Array.from({length:Math.min(m.total,8)},(_,i)=>{const k=i<m.ok?'成功':i<m.ok+m.fail?'失败':i<m.ok+m.fail+m.skip?'跳过':i<m.ok+m.fail+m.skip+m.unknown?'待确认':'未处理';const address=m.origin==='window'?windowRows[i%8][1]:m.id==='9826'?importAddresses[i]:m.state==='retried'?'198.51.100.88:1080':proxyRows[i%8][1];const why=k==='失败'?(m.type==='批量检测'?'连接超时':m.id==='9818'?'输入地址无效':'保存失败'):k==='跳过'?(i===m.total-1?'未选择或无需修改':'记录已存在'):k==='待确认'?'连接中断，尚未核实是否生效':k==='未处理'?'等待处理':'已确认完成';return `<tr><td>${i+1}</td><td>${address}</td><td>${badge(k,k==='成功'?'green':k==='失败'?'red':k==='待确认'?'orange':'')}</td><td>${why}</td></tr>`}).join('');
if(m.id==='9826'&&m.state==='running'){const values=['成功','成功','成功','未处理','跳过','跳过'];items=values.map((k,i)=>`<tr><td>${i+1}</td><td class="mono">${importAddresses[i]}</td><td>${badge(k,k==='成功'?'green':'')}</td><td>${k==='成功'?'已确认完成':k==='未处理'?'等待处理':i===4?'记录已存在':'未选择导入'}</td></tr>`).join('')}
const localTask=m.origin==='window'||m.type==='批量检测';const footer=role==='operator'&&m.fail?btn('重试失败项','t-retry','primary'):role==='operator'&&m.unknown?btn('核实待确认项','!task-verify','primary'):m.state==='running'?btn('刷新进度','!task-refresh','primary'):m.state==='waiting'&&role==='operator'?btn('重新连接后核实','!task-reconnect','primary'):['success','partial','retried'].includes(m.state)?btn('查看相关资源',roleList(m.origin),'primary'):'';
return drawer('任务详情',`<div class="task-title"><div><span class="tiny muted">任务 ID ${m.id}</span><h2>${m.name}</h2></div>${badge(...(taskLabels[m.state]||taskLabels.partial))}</div>${noticeText}`+facts([['任务类型',m.type],['发起人','林予安'],['发起时间',m.started||'2026-10-27 14:46'],['最近更新',m.started||'2026-10-27 14:46'],['执行方式',localTask?'林予安的桌面端':'系统处理'],...(m.source?[['原任务',`<button class="btn text" data-task-id="${m.source}" data-go="t-result">任务 ${m.source}</button>`]]:[])])+`<div class="task-counts">${[[m.total,'总数'],[m.ok,'成功'],[m.fail,'失败'],[m.skip,'跳过'],[m.unknown,'待确认'],[m.pending,'未处理']].map(([n,t])=>`<div><strong>${n}</strong><span>${t}</span></div>`).join('')}</div>${m.state==='running'?'<div class="progress"><span style="width:83.33%"></span></div><span class="tiny muted">已处理 5 / 6 条</span>':''}<div class="section"><h3>逐项结果</h3><table class="dense task-items"><thead><tr><th>序号</th><th>提交内容</th><th>结果</th><th>原因 / 后续</th></tr></thead><tbody>${items}</tbody></table>${m.total>8?`<div class="pagination"><span>共 ${m.total} 条</span><span>8 条 / 页　1　2　3　…</span></div>`:''}</div>${role!=='operator'&&localTask?'<p class="tiny muted" style="margin-top:15px">需要继续处理时，请由对应运营在原桌面端执行。</p>':''}`,footer,true)}
function retryTask(){const m=jobModel(retrySource==='9826'?'partial':'partial',retrySource);return dialog('重试失败项',facts([['原任务',m.id+' · '+m.name],['重试范围',m.fail+' 条失败记录'],['已成功记录',m.ok+' 条，不重复处理'],['跳过记录',m.skip+' 条，不纳入重试']])+notice('将创建关联的新任务','原任务及逐项结果保留。'),btn('取消','t-result')+btn('确认重试','!task-retry','primary'))}
